<?php
require __DIR__.'/lib.php';require_login();
try{if(!adjustments_ready())throw new Exception('Run the Adjustments & Reports upgrade first.');$r=inventory_report_build($_GET);$format=$_GET['format']??'';if($format==='print'){report_print_document($r['title'],$r['headers'],report_export_rows($r),report_meta($r));exit;}if($format!=='xlsx')throw new Exception('Choose Download Excel or Print / Save as PDF.');$path=tempnam(sys_get_temp_dir(),'rs8-report-');try{report_write_xlsx($path,$r['title'],$r['headers'],report_export_rows($r),report_meta($r));header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="'.preg_replace('/[^A-Za-z0-9_-]/','_',$r['title']).'_'.date('Ymd_His').'.xlsx"');header('Cache-Control: private, no-store');readfile($path);}finally{if(is_file($path))unlink($path);}}catch(Throwable $ex){http_response_code(400);echo '<h1>Report unavailable</h1><p>'.e(safe_error_message($ex)).'</p><a href="index.php?page=reports">Back to Reports</a>';}
